import { AgentContext } from '../../../../../domain/core/agents/agentContext';
import { afterEach, expect, it, vi } from 'vitest';
import type { DiagramGenerationRequest } from '../../../../../domain/core/diagrams/diagramGeneration';
import { revisionFixture } from '../../../../../tests/support/diagramRevisions';

type Tool = { execute(id: string, candidate: unknown): Promise<{ details: { accepted: boolean } }> };
const harness = vi.hoisted(() => ({
  actions: [] as ((tool: Tool) => Promise<void>)[],
  chats: [] as { history: unknown[]; prompts: string[]; abort: ReturnType<typeof vi.fn>; dispose: ReturnType<typeof vi.fn> }[]
}));
vi.mock('@earendil-works/pi-coding-agent', () => ({
  ModelRuntime: { create: async () => ({ getModel: (_provider: string, id: string) => ({ id }), hasConfiguredAuth: () => true }) },
  DefaultResourceLoader: class { async reload() {} }, getAgentDir: () => '/tmp',
  SessionManager: { create: () => ({ messages: [] as unknown[], appendMessage(message: unknown) { this.messages.push(message); } }) }, SettingsManager: { inMemory: () => ({}) }, defineTool: (tool: unknown) => tool,
  createAgentSession: async (options: { customTools: Tool[]; sessionManager: { messages: unknown[] } }) => {
    const chat = { history: structuredClone(options.sessionManager.messages), prompts: [] as string[], abort: vi.fn(async () => {}), dispose: vi.fn() };
    const messages = structuredClone(chat.history);
    const tool: Tool = { execute: async (id, candidate) => {
      messages.push({ role: 'assistant', content: [{ type: 'toolCall', id, name: 'submit_diagram', arguments: candidate }] });
      const result = await options.customTools[0].execute(id, candidate);
      messages.push({ role: 'toolResult', toolCallId: id, toolName: 'submit_diagram', content: [{ type: 'text', text: JSON.stringify(result) }], isError: false });
      return result;
    } };
    harness.chats.push(chat);
    return { session: { sessionId: 'test', messages, ...chat, subscribe: () => () => {}, prompt: async (text: string) => {
      chat.prompts.push(text); messages.push({ role: 'user', content: text }); await harness.actions.shift()?.(tool);
    } } };
  }
}));
import { PiDiagramEditRuntime, renderDiagramEditPrompt } from '../diagramEditRuntime';
afterEach(() => { harness.actions.length = 0; harness.chats.length = 0; vi.clearAllMocks(); });
function fixture() {
  const runtime = new PiDiagramEditRuntime('/tmp', true), service = revisionFixture(runtime);
  const base = service.create({ id: crypto.randomUUID(), revision: 0, ascii: 'Original' });
  const request: DiagramGenerationRequest = { input: { id: base.diagram.id }, instruction: 'Add a child', baseRevisionId: base.revision.id,
    context: { diagram: base.diagram, selection: { startLine: 1, endLine: 1, startColumn: 1, endColumn: 8 } } };
  return { runtime, service, base, request };
}
it('corrects rejected submissions in one agent session and issues only the validated revision', async () => {
  const f = fixture();
  harness.actions.push(async tool => {
    expect((await tool.execute('blank', { ascii: ' ', structureKind: 'tree', mappings: [] })).details.accepted).toBe(false);
    expect((await tool.execute('unknown-source', { ascii: 'Root', structureKind: 'tree', mappings: [
      { id: 'm', entityId: 'invented', sourceRangeIndex: 0, line: 1, startColumn: 1, endColumn: 4 }
    ] })).details.accepted).toBe(false);
    expect(f.service.listRevisions(f.base.diagram.diagramId)).toHaveLength(1);
    expect((await tool.execute('valid', { ascii: 'Root\n`-- Child', structureKind: 'tree', mappings: [] })).details.accepted).toBe(true);
  });
  const result = await f.service.generate(f.request);
  expect(result.diagram.content.ascii).toBe('Root\n`-- Child');
  expect(result.revision.parentId).toBe(f.base.revision.id);
  expect(f.service.listRevisions(f.base.diagram.diagramId)).toHaveLength(2);
  expect(harness.chats[0].prompts[0]).toContain(f.base.revision.id);
  expect(harness.chats[0].prompts[0]).toContain('Add a child');
  expect(harness.chats[0].dispose).toHaveBeenCalledOnce(); f.runtime.dispose();
});

it('captures and reuses the full successful transcript, including tool results', async () => {
  const f = fixture(), captured = vi.fn(), session = vi.fn();
  harness.actions.push(async tool => { await tool.execute('first', { ascii: 'First', structureKind: 'tree', mappings: [] }); });
  await f.service.generate({ ...f.request, llmSessionId: 'panel' }, { onAgentContext: captured, onAgentSession: session });
  expect(session).toHaveBeenCalledWith('test');
  const first = captured.mock.calls[0][0];
  expect(first.source.sourceSessionId).toBe('panel');
  expect(first.messages.map((m: { role: string }) => m.role)).toEqual(['user', 'assistant', 'toolResult']);
  harness.actions.push(async tool => { await tool.execute('second', { ascii: 'Second', structureKind: 'tree', mappings: [] }); });
  await f.service.generate({ ...f.request, llmSessionId: 'panel', agentContext: first, instruction: 'Continue the previous request' }, { onAgentContext: captured });
  expect(harness.chats[1].history).toEqual(AgentContext.fromSnapshot(first).toPiMessages());
  expect(captured.mock.calls[1][0].messages).toHaveLength(6);
  expect(captured.mock.calls[1][0].messages.slice(0, 3)).toEqual(expect.arrayContaining(first.messages.map((m: object) => expect.objectContaining(m))));
  await expect(f.service.generate({ ...f.request, llmSessionId: 'panel', agentContext: first }, { onAgentContext: captured })).rejects.toThrow('without a validated submission');
  expect(captured).toHaveBeenCalledTimes(2);
  f.runtime.dispose();
});
it('requires a validated submission and cleans up on cancellation', async () => {
  const f = fixture();
  await expect(f.service.generate(f.request)).rejects.toThrow('without a validated submission');
  expect(harness.chats[0].dispose).toHaveBeenCalledOnce();
  const abort = new AbortController();
  harness.actions.push(async () => { abort.abort(Error('cancelled')); });
  await expect(f.service.generate(f.request, { signal: abort.signal })).rejects.toThrow('cancelled');
  expect(harness.chats[1].abort).toHaveBeenCalledOnce(); expect(harness.chats[1].dispose).toHaveBeenCalledOnce();
  expect(f.service.listRevisions(f.base.diagram.diagramId)).toHaveLength(1); f.runtime.dispose();
});
it('renders prompt values once, preserving literal template markers in user content', () => {
  const f = fixture(), markdown = 'CONTEXT {{context}}\nREFS {{references}}\nSTYLE {{options.style}} {{options.detail}}\nINSTRUCTION {{instruction}}';
  const parameters = [{ kind: 'enum' as const, key: 'style', options: [{ value: 'minimal', guidance: 'Fewest boxes.' }] }, { kind: 'number' as const, key: 'detail' }];
  const prompt = { markdown, options: { style: 'minimal', detail: 2 }, parameters, references: [{ ref: 1, label: '{{instruction}}' }] };
  const result = renderDiagramEditPrompt({ ...f.request, prompt, instruction: '{{context}}\nKeep this literal' });
  expect(result).toContain('INSTRUCTION "{{context}}\\nKeep this literal"');
  expect(result).toContain('STYLE Fewest boxes. 2');
  expect(result).toContain('REFS [{"ref":1,"label":"{{instruction}}"}]');
  expect(() => renderDiagramEditPrompt({ ...f.request, prompt: { ...prompt, markdown: `${markdown} {{unknown}}` } })).toThrow('Unknown');
  expect(renderDiagramEditPrompt(f.request)).toContain(f.base.revision.id);
  f.runtime.dispose();
});

it('seeds uploaded trajectory before the current task and starts a fresh history for each run', async () => {
  const f = fixture();
  const context = AgentContext.fromTrajectory({ agentType: 'claude', sourceSessionId: 'source', format: 'messages-v1',
    fromEntryId: 'one', throughEntryId: 'one', entries: [{ id: 'one', parentId: null,
      message: { role: 'user', content: [{ type: 'text', text: 'The new cache belongs to Workspace.' }] } }] });
  harness.actions.push(async tool => { await tool.execute('valid', { ascii: 'Workspace\n`-- Cache', structureKind: 'tree', mappings: [] }); });
  await f.service.generate({ ...f.request, agentContext: context.toSnapshot() });
  expect(harness.chats[0].history).toEqual(context.toPiMessages());
  expect(harness.chats[0].prompts).toHaveLength(1);
  expect(harness.chats[0].prompts[0]).toContain('Add a child');
  await expect(f.service.generate(f.request)).rejects.toThrow('without a validated submission');
  expect(harness.chats[1].history).toEqual([]);
  expect(context.toSnapshot().messages).toHaveLength(1);
  f.runtime.dispose();
});

it.each(['edit-diagram', 'create-diagram', 'extend-diagram'] as const)('ends the condensed %s prompt with the output contract', operation => {
  const f = fixture();
  const prompt = renderDiagramEditPrompt({ ...f.request, operation });
  const output = prompt.slice(prompt.lastIndexOf('# OUTPUT FORMAT'));
  expect(prompt).toContain('## User instruction (JSON string)');
  expect(output).toContain('## ASCII and structure');
  expect(output).toContain('## Source mappings');
  expect(output).toContain('## Submission');
  expect(output).toContain('Omit mappings');
  expect(output).not.toContain('requestId');
  expect(prompt.endsWith('Never claim success without submitting.')).toBe(true);
  expect(prompt).not.toContain('Preserve logical node identities: append');
  const enabled = renderDiagramEditPrompt({ ...f.request, operation, sourceMappings: true });
  expect(enabled).toContain('complete array');
  expect(enabled).toContain('Use only supplied evidence IDs');
  if (operation !== 'edit-diagram') {
    expect(prompt).toContain('Do not use [[keep:...]]');
    expect(prompt).not.toContain('You may choose whether to preserve node continuity');
  }
});

it('resolves source references for the model and preserves descriptors when capturing the next context', async () => {
  const f = fixture(), captured = vi.fn();
  const reference = { type: 'sourceRange' as const, sourceId: 'source', path: 'code.ts', startLine: 2, endLine: 2,
    version: { kind: 'snapshot' as const, contentHash: 'a'.repeat(64) } };
  const original = AgentContext.fromMessages('panel', [{ role: 'user', timestamp: 0, content: [reference] }]).toSnapshot();
  const read = vi.fn(async () => 'code.ts:2-2\nconst pinned = 42;');
  const runtime = new PiDiagramEditRuntime('/tmp', true, { read, capture: vi.fn(), persist: vi.fn(), portable: vi.fn() });
  harness.actions.push(async tool => { await tool.execute('first', { ascii: 'First', structureKind: 'tree', mappings: [] }); });
  await runtime.generate({ ...f.request, llmSessionId: 'panel', agentContext: original }, { onAgentContext: captured });
  expect(read).toHaveBeenCalledWith(reference);
  expect(harness.chats[0].history[0]).toMatchObject({ content: [{ type: 'text', text: 'code.ts:2-2\nconst pinned = 42;' }] });
  const next = captured.mock.calls[0][0];
  expect(next.messages[0]).toEqual(original.messages[0]);
  expect(JSON.stringify(next)).not.toContain('const pinned');
  expect(next.version).toBe(2);
  harness.actions.push(async tool => { await tool.execute('second', { ascii: 'Second', structureKind: 'tree', mappings: [] }); });
  await runtime.generate({ ...f.request, llmSessionId: 'panel', agentContext: next }, { onAgentContext: captured });
  expect(captured.mock.calls[1][0].messages[0]).toEqual(original.messages[0]);
  expect(JSON.stringify(captured.mock.calls[1][0])).not.toContain('const pinned');
  runtime.dispose(); f.runtime.dispose();
});

it('does not create a model session when cancelled during lazy source resolution', async () => {
  const f = fixture(), abort = new AbortController();
  const snapshot = AgentContext.fromMessages('panel', [{ role: 'user', timestamp: 0, content: [{ type: 'sourceRange',
    sourceId: 'source', path: 'code.ts', startLine: 1, endLine: 1, version: { kind: 'snapshot', contentHash: 'a'.repeat(64) } }] }]).toSnapshot();
  let release!: (text: string) => void;
  const pending = new Promise<string>(resolve => { release = resolve; });
  const read = vi.fn(() => pending);
  const runtime = new PiDiagramEditRuntime('/tmp', true, { read, capture: vi.fn(), persist: vi.fn(), portable: vi.fn() });
  const run = runtime.generate({ ...f.request, agentContext: snapshot }, { signal: abort.signal });
  const rejected = expect(run).rejects.toThrow('cancelled');
  await vi.waitFor(() => expect(read).toHaveBeenCalledOnce());
  abort.abort(Error('cancelled')); release('source text');
  await rejected;
  expect(harness.chats).toHaveLength(0);
  runtime.dispose(); f.runtime.dispose();
});

import type { AgentSession } from '@earendil-works/pi-coding-agent';
import { AgentContext, type AgentContextMessage } from '../../../../domain/core/agents/agentContext';

/** Strip SDK metadata and private reasoning blocks while preserving the complete
 * user/assistant/tool transcript used for subsequent composer requests. */
export function captureDiagramAgentContext(sessionId: string, messages: Readonly<AgentSession['messages']>, imported?: { original: AgentContext; resolved: AgentContext }) {
  const captured: AgentContextMessage[] = [];
  for (const message of messages) {
    if (message.role === 'user') {
      const content = typeof message.content === 'string' ? [{ type: 'text' as const, text: message.content }]
        : message.content.filter(block => block.type === 'text').map(block => ({ type: 'text' as const, text: block.text }));
      if (content.length) captured.push({ role: 'user', content, timestamp: message.timestamp });
    } else if (message.role === 'assistant') {
      const content: Extract<AgentContextMessage, { role: 'assistant' }>['content'] = [];
      for (const block of message.content) {
        if (block.type === 'text') content.push({ type: 'text', text: block.text });
        else if (block.type === 'toolCall') content.push({ type: 'toolCall', id: block.id, name: block.name, arguments: block.arguments });
      }
      if (content.length) captured.push({ role: 'assistant', content, timestamp: message.timestamp });
    } else if (message.role === 'toolResult') {
      const content = message.content.filter(block => block.type === 'text').map(block => ({ type: 'text' as const, text: block.text }));
      captured.push({ role: 'toolResult', toolCallId: message.toolCallId, toolName: message.toolName,
        content: content.length ? content : [{ type: 'text', text: '[Non-text tool result]' }], isError: message.isError, timestamp: message.timestamp });
    } else if (message.role === 'compactionSummary' || message.role === 'branchSummary') {
      captured.push({ role: 'user', content: [{ type: 'text', text: `Previous conversation summary:\n${message.summary}` }], timestamp: message.timestamp });
    }
  }
  // Replace only an unchanged imported prefix. A compacted/edited transcript must not
  // have unrelated messages replaced merely because their text happens to match.
  const original = imported?.original.toSnapshot(), resolved = imported?.resolved.toSnapshot();
  const semantic = ({ timestamp: _, ...message }: AgentContextMessage) => JSON.stringify(message);
  const normalized = AgentContext.fromMessages(sessionId, captured).toSnapshot().messages;
  if (original && resolved && resolved.messages.every((message, index) => normalized[index] && semantic(normalized[index]) === semantic(message))) {
    normalized.splice(0, resolved.messages.length, ...original.messages);
    const context = AgentContext.fromMessages(sessionId, normalized);
    return AgentContext.fromSnapshot({ ...context.toSnapshot(), ...(original.sourceFiles ? { sourceFiles: original.sourceFiles } : {}) }).toSnapshot();
  }
  return AgentContext.fromMessages(sessionId, normalized).toSnapshot();
}

import { diagramContentNodes } from '../../../../domain/core/diagrams/diagramContentNodes';
import { scopedReplacements } from '../../../../domain/core/diagrams/diagramSubtreeEdit';
import { captureDiagramAgentContext } from './diagramAgentContext';
import type { AgentContextSources } from '../../../../application/core/ports/agentContextSources';
import { AgentContext } from '../../../../domain/core/agents/agentContext';
import { Type } from '@earendil-works/pi-ai';
import { DefaultResourceLoader, defineTool, getAgentDir, SettingsManager } from '@earendil-works/pi-coding-agent';
import type { DiagramGenerationRequest, DiagramGenerator, GenerationOptions } from '../../../../domain/core/diagrams/diagramGeneration';
import { validateGeneratedDiagramEdit, type GeneratedDiagramEdit } from '../../../../domain/core/diagrams/generatedDiagramEdit';
import { diagramOutputFormat, defaultTemplateSelection, renderPromptTemplate, resolvePromptTemplate } from '../../../../domain/mapping/agent/promptTemplates';
import { PiAgentRuntime, progressFor } from '../../../core/agents/agentRuntime';
import { createValidatedSubmission } from '../../../core/agents/validatedSubmission';

/** Renders the request's validated template; requests without one use the default edit template. */
export function renderDiagramEditPrompt(request: DiagramGenerationRequest) {
  if (!request.context) throw Error('Diagram generation requires captured context');
  const prompt = request.prompt ?? (() => {
    const template = resolvePromptTemplate(defaultTemplateSelection(request.operation ?? 'edit-diagram'), request.operation ?? 'edit-diagram');
    return { markdown: template.markdown, options: template.options, parameters: template.definition.parameters, references: [] };
  })();
  const ranges = request.editRanges?.length ? request.editRanges : request.editRange ? [request.editRange] : [];
  return renderPromptTemplate(prompt, {
    context: JSON.stringify({ baseRevisionId: request.baseRevisionId ?? null, diagram: request.context.diagram, editableRanges: ranges,
      logicalNodes: request.baseRevisionId ? diagramContentNodes(request.context.diagram.content).map(node => ({ line: node.line, nodeRef: request.nodeRefs?.[node.id] })) : [],
      generationOptions: prompt.options, connections: request.context.connections ?? [] }),
    references: JSON.stringify(prompt.references), instruction: JSON.stringify(request.instruction)
  }) + '\n\n' + diagramOutputFormat(request.operation ?? 'edit-diagram', request.sourceMappings ?? false);

}

export class PiDiagramEditRuntime extends PiAgentRuntime implements DiagramGenerator {
  constructor(private readonly sourceRoot: string, enabled = false, private readonly sources?: AgentContextSources) { super(enabled); }
  async generate(request: DiagramGenerationRequest, options: GenerationOptions) {
    this.requireEnabled();
    const base = request.context?.diagram;
    if (!base) throw Error('Diagram edit context is required');
    options.signal?.throwIfAborted();
    const configured = await this.model();
    const prompt = renderDiagramEditPrompt(request);
    const submission = createValidatedSubmission<GeneratedDiagramEdit>({
      toolName: 'submit_diagram_edit',
      validate: candidate => { try { const clean = validateGeneratedDiagramEdit(base, candidate, request.nodeRefs, request.sourceMappings); const ranges = request.editRanges?.length ? request.editRanges : request.editRange ? [request.editRange] : []; if (ranges.length) { if (clean.structureKind !== base.content.structure.kind) throw Error('REPLACEMENT_SCOPE: preserve structure kind'); scopedReplacements(base, clean.ascii, ranges, clean.replacementRanges); } } catch (error) { return String(error); } },
      acceptedMessage: () => 'Validated diagram edit submitted.'
    });
    const submit = defineTool({
      name: 'submit_diagram_edit', label: 'Submit diagram edit',
      description: 'Submit the complete revised ASCII and mappings into the supplied evidence.',
      promptSnippet: 'Submit a complete revised diagram', promptGuidelines: [submission.promptGuideline],
      parameters: Type.Object({
        ascii: Type.String({ minLength: 1, maxLength: 200000 }),
        replacementRanges: Type.Optional(Type.Array(Type.Object({ startLine: Type.Integer({ minimum: 1 }), endLine: Type.Integer({ minimum: 0 }) }), { minItems: 1, maxItems: 100 })),
        structureKind: Type.Union([Type.Literal('diagram'), Type.Literal('tree')]),
        mappings: Type.Optional(Type.Array(Type.Object({
          id: Type.String(), entityId: Type.String(), sourceRangeIndex: Type.Integer({ minimum: 0 }),
          sourceRangeId: Type.Optional(Type.String()), line: Type.Integer({ minimum: 1 }),
          startColumn: Type.Integer({ minimum: 1 }), endColumn: Type.Integer({ minimum: 1 })
        }), { maxItems: 2000 }))
      }),
      execute: (id, candidate) => submission.execute(id, candidate)
    });
    const settingsManager = SettingsManager.inMemory({
      defaultProvider: configured.provider,
      defaultModel: configured.modelId, defaultThinkingLevel: 'medium'
    });
    const resourceLoader = new DefaultResourceLoader({
      cwd: this.sourceRoot, agentDir: getAgentDir(), settingsManager,
      noExtensions: true, noSkills: true, noPromptTemplates: true, noThemes: true, noContextFiles: true,
      systemPrompt: 'You create and edit ASCII diagrams using captured context. Follow the specification and finish with a validated submit_diagram_edit tool call.'
    });
    await resourceLoader.reload(); options.signal?.throwIfAborted();
    const imported = request.agentContext ? AgentContext.fromSnapshot(request.agentContext) : undefined;
    const agentContext = imported ? await imported.resolveSources(this.sources ? ref => this.sources!.read(ref) : undefined) : undefined;
    options.signal?.throwIfAborted();
    const { session } = await this.createSession({
      cwd: this.sourceRoot, modelRuntime: configured.runtime, model: configured.model,
      thinkingLevel: 'medium', tools: ['submit_diagram_edit'], customTools: [submit], resourceLoader, settingsManager
    }, agentContext);
    options.onAgentSession?.(session.sessionId);
    const unsubscribe = session.subscribe(event => {
      const progress = progressFor(event, `${configured.provider}/${configured.modelId}`, session.sessionId);
      if (progress) options.onProgress?.(progress.message);
    });
    const abort = () => { void session.abort().catch(() => { }); };
    options.signal?.addEventListener('abort', abort, { once: true });
    try {
      options.signal?.throwIfAborted();
      await session.prompt(prompt);
      options.signal?.throwIfAborted();
      if (!submission.value) throw Error('Diagram edit agent finished without a validated submission');
      const candidate = validateGeneratedDiagramEdit(base, submission.value, request.nodeRefs, request.sourceMappings);
      if (request.llmSessionId) options.onAgentContext?.(captureDiagramAgentContext(request.llmSessionId, session.messages, imported && agentContext ? { original: imported, resolved: agentContext } : undefined));
      return { ...candidate, source: base.sourceContext.binding, evidence: base.sourceContext.evidence };
    } finally {
      options.signal?.removeEventListener('abort', abort); unsubscribe(); session.dispose(); this.sessions.delete(session);
    }
  }
}

export class FakeDiagramEditRuntime implements DiagramGenerator {
  async generate(request: DiagramGenerationRequest, options: GenerationOptions) {
    options.signal?.throwIfAborted();
    const base = request.context!.diagram, instruction = request.instruction.replace(/[\r\n]/g, ' ');
    options.onAgentSession?.(`fake-agent-${crypto.randomUUID()}`);
    if (request.llmSessionId) options.onAgentContext?.(AgentContext.fromMessages(request.llmSessionId, [
      ...(request.agentContext?.messages ?? []),
      { role: 'user', content: [{ type: 'text', text: request.instruction }], timestamp: 0 },
      { role: 'assistant', content: [{ type: 'text', text: `Generated diagram for: ${request.instruction}` }], timestamp: 0 },
    ]).toSnapshot());
    options.onProgress?.('Generating fake diagram edit');
    if (!request.baseRevisionId) return {
      ascii: `[created: ${instruction}]`, structureKind: 'diagram' as const, mappings: [],
      source: base.sourceContext.binding, evidence: base.sourceContext.evidence
    };
    const lines = base.content.ascii.split('\n');
    const ranges = request.editRanges?.length ? request.editRanges : request.editRange ? [request.editRange] : [];
    if (ranges.length) for (const range of ranges) lines[range.startLine - 1] += ` [edited: ${instruction}]`;
    else lines.push(`[edited: ${instruction}]`);
    const nodes = diagramContentNodes(base.content);
    return {
      ...(ranges.length ? { replacementRanges: ranges } : {}), nodeCorrespondence: Object.fromEntries(nodes.filter(node => nodes.filter(other => other.line === node.line).length === 1 && request.nodeRefs?.[node.id]).map(node => [request.nodeRefs![node.id], node.line])), ascii: lines.join('\n'),
      structureKind: base.content.structure.kind, ...(request.sourceMappings ? { mappings: [...base.sourceContext.mappings] } : {}),
      source: base.sourceContext.binding, evidence: base.sourceContext.evidence
    };
  }
  dispose() { }
}

